insert into onb_screens (id, sort, kind, title_de, title_en, short_de, short_en, intro_de, intro_en, active) values
  ('project', 10, 'questions', 'Ihr Projekt', 'Your project', 'Projekt', 'Project', 'In diesem Abschnitt geht es um Sie und das Paket, das Sie gebucht haben. Bitte prüfen Sie alles, was wir aus Ihrem Angebot übernommen haben, denn es ist nicht immer aktuell.', 'This section is about you and the package you booked. Please check anything we have carried over from your quote, because it is not always up to date.', true),
  ('business', 20, 'questions', 'Unternehmensdaten', 'Business details', 'Unternehmen', 'Business', 'Dieser Abschnitt baut Ihre Rechtsseiten. Bitte nehmen Sie diese Angaben aus Ihrem Registereintrag oder einer aktuellen Rechnung, denn sie stehen Wort für Wort auf Ihrer Seite.', 'This section builds your legal pages. Please take these details from your register entry or a recent invoice, because they appear on your site word for word.', true),
  ('inboxes', 30, 'questions', 'Postfächer und Benachrichtigungen', 'Inboxes and notifications', 'Postfächer', 'Inboxes', 'In diesem Abschnitt geht es um Ihre Postfächer und Benachrichtigungen. Bitte sagen Sie uns, über welche Adressen Sie erreichbar sind und wer erfahren soll, wenn eine Nachricht eingeht. Das ist nicht immer dasselbe.', 'This section is about your inboxes and notifications. Please tell us which addresses people can use to reach you and who should hear about it when a message arrives. They are not always the same.', true),
  ('design', 40, 'questions', 'Wie Ihre Seite aussehen und klingen soll', 'How your site should look and sound', 'Auftritt', 'Look & sound', 'In diesem Abschnitt geht es darum, wie Ihre Website aussehen und klingen soll. Bitte werden Sie so konkret wie möglich, denn alles auf diesem Bildschirm fließt direkt in Ihren ersten Entwurf.', 'This section is about how your website should look and sound. Please be as specific as you can, because everything on this screen goes straight into your first design.', true),
  ('pages', 50, 'questions', 'Seitenstruktur', 'Page structure', 'Seiten', 'Pages', 'In diesem Abschnitt geht es um die Struktur und die Seiten Ihrer Website. Bitte beginnen Sie mit Ihrem Angebot, denn daraus ergeben sich meist Ihre Seiten.', 'This section is about the structure and pages of your website. Please start with what you offer, because your pages usually follow from it.', true),
  ('integrations', 60, 'questions', 'Verbundene Systeme', 'Integrations and connected systems', 'Systeme', 'Systems', 'In diesem Abschnitt geht es um die Systeme, mit denen Ihre Website verbunden sein soll: Karten, Bewertungen, Buchung, Zahlungen oder Newsletter. Bitte geben Sie uns die Links, damit wir sie anbinden können.', 'This section is about the integrations your website needs, such as maps, reviews, booking, payments or your newsletter. Please give us the links so we can connect them to your site.', true),
  ('files', 70, 'questions', 'Logo, Fotos und Dateien', 'Logo, photos and files', 'Dateien', 'Files', 'In diesem Abschnitt geht es um die Dateien, aus denen wir Ihre Website bauen: Logo, Fotos und Dokumente. Bitte achten Sie darauf, dass ein Ordnerlink freigegeben ist, damit wir ihn öffnen können.', 'This section is about the files we build your website from: your logo, your photos and any documents. Please make sure any folder link you send is shared, so we can open it.', true),
  ('access_legal', 80, 'questions', 'Zugänge und Rechtliches', 'Access and legal', 'Zugänge & Recht', 'Access & legal', 'In diesem Abschnitt geht es um die Konten, von denen Ihre Website abhängt, und um die Rechtsseiten, die sie braucht. Bitte nur Namen und Anbieter, niemals Passwörter.', 'This section is about the accounts your website depends on and the legal pages it needs. Please give us names and providers only, never passwords.', true),
  ('timing', 90, 'questions', 'Zeitplan', 'Timing', 'Zeitplan', 'Timing', 'In diesem Abschnitt geht es um den Zeitplan. Bitte nennen Sie realistische Termine statt erhoffter, denn wir planen den ganzen Bau darum herum.', 'This section is about timing. Please give us realistic dates rather than hopeful ones, because we plan the whole build around them.', true),
  ('review', 100, 'review', 'Prüfen und bestätigen', 'Review and confirm', 'Abschluss', 'Review', null, null, true)
on conflict (id) do update set sort = excluded.sort, kind = excluded.kind, title_de = excluded.title_de, title_en = excluded.title_en, short_de = excluded.short_de, short_en = excluded.short_en, intro_de = excluded.intro_de, intro_en = excluded.intro_en, active = excluded.active;

insert into onb_fields (id, screen_id, sort, type, label_de, label_en, help_de, help_en, placeholder_de, placeholder_en, required, allow_dont_know, ai_check, options, config, show_when, active) values
  ('contact_name', 'project', 10, 'text', 'Wie heißen Sie?', 'What is your name?', null, null, 'Anna Meier', 'Anna Meier', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('contact_company', 'project', 20, 'text', 'Wie heißt Ihr Unternehmen?', 'What is your company called?', null, null, 'Müller Sanitär GmbH', 'Müller Sanitär GmbH', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('contact_email', 'project', 30, 'email', 'Wie lautet Ihre E-Mail-Adresse?', 'What is your email address?', 'Hierhin schicken wir Ihren Speicherlink und am Ende Ihr fertiges Briefing.', 'We will send your save link here and your finished brief at the end.', 'anna@mueller-sanitaer.de', 'anna@mueller-sanitaer.de', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('booked_package', 'project', 40, 'radio', 'Welches Paket haben Sie gebucht?', 'Which package did you book?', null, null, null, null, true, true, false, '[{"value":"silver","label_de":"Silver","label_en":"Silver"},{"value":"gold","label_de":"Gold","label_en":"Gold"},{"value":"platinum","label_de":"Platinum","label_en":"Platinum"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('booked_page_band', 'project', 50, 'radio', 'Wie viele Seiten umfasst Ihr Angebot?', 'How many pages does your quote cover?', 'Das steht in Ihrem Angebot, als die Konfiguration, die Sie bestätigt haben.', 'It is on your quote, as the configuration you confirmed.', null, null, true, true, false, '[{"value":"14","label_de":"1 bis 4 Seiten","label_en":"1 to 4 pages","min":1,"max":4},{"value":"58","label_de":"5 bis 8 Seiten","label_en":"5 to 8 pages","min":5,"max":8},{"value":"912","label_de":"9 bis 12 Seiten","label_en":"9 to 12 pages","min":9,"max":12},{"value":"12p","label_de":"Mehr als 12 Seiten","label_en":"More than 12 pages","min":13,"max":null}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('project_type', 'project', 60, 'radio', 'Ist das eine ganz neue Website oder eine Änderung an Ihrer bestehenden?', 'Is this a brand new website, or changes to one you already have?', null, null, null, null, true, false, false, '[{"value":"new","label_de":"Eine ganz neue Website","label_en":"A brand new website"},{"value":"changes","label_de":"Änderungen an meiner bestehenden Seite","label_en":"Changes to my existing site"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('existing_url', 'project', 70, 'url', 'Wie lautet Ihre aktuelle Website-Adresse?', 'What is your current website address?', null, null, 'https://www.mueller-sanitaer.de', 'https://www.mueller-sanitaer.de', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"project_type","values":["changes"]}]'::jsonb, true),
  ('legal_name', 'business', 80, 'text', 'Wie lautet Ihr vollständiger Firmenname?', 'What is your full legal company name?', 'Genau so, wie er im Registereintrag oder auf Ihren Rechnungen steht, nicht so, wie er auf Ihrer aktuellen Website steht.', 'Exactly as it appears on your register entry or your invoices, not as it appears on your current website.', 'Müller Sanitär GmbH', 'Müller Sanitär GmbH', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('legal_form', 'business', 90, 'text', 'Welche Rechtsform hat Ihr Unternehmen?', 'What is your legal form?', null, null, 'GmbH', 'GmbH', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('address_street', 'business', 100, 'text', 'Wie lautet Ihre Straße und Hausnummer?', 'What is your street and number?', null, null, 'Hauptstraße 14', 'Hauptstraße 14', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('address_city', 'business', 110, 'text', 'Wie lauten Postleitzahl und Ort?', 'What is your postcode and city?', null, null, '80331 München', '80331 München', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('vat_id', 'business', 120, 'text', 'Wie lautet Ihre USt-IdNr.?', 'What is your VAT ID?', null, null, 'DE123456789', 'DE123456789', false, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('register_entry', 'business', 130, 'text', 'Wie lauten Registergericht und Registernummer?', 'What is your register court and number?', 'Bitte frei lassen, wenn Sie keine haben.', 'Please leave it blank if you do not have one.', 'Amtsgericht München, HRB 12345', 'Amtsgericht München, HRB 12345', false, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('content_responsible', 'business', 140, 'text', 'Wer ist für den Inhalt Ihrer Website verantwortlich?', 'Who is responsible for the content on your website?', 'Die benannte Person nach § 18 Abs. 2 MStV, meist die Inhaberin oder der Geschäftsführer.', 'The named person under § 18 Abs. 2 MStV, usually the owner or managing director.', 'Anna Meier', 'Anna Meier', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('public_phone', 'business', 150, 'tel', 'Welche Telefonnummer sollen wir auf der Seite zeigen?', 'What phone number should we show on the site?', null, null, '+49 89 1234567', '+49 89 1234567', false, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('public_email', 'business', 160, 'email', 'Welche E-Mail-Adresse sollen wir auf der Seite zeigen?', 'What email address should we show on the site?', 'Das muss nicht die Adresse sein, mit der Sie dieses Formular ausfüllen.', 'This may not be the one you are using to fill in the form.', 'info@mueller-sanitaer.de', 'info@mueller-sanitaer.de', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('opening_hours', 'business', 170, 'textarea', 'Wie sind Ihre Öffnungszeiten?', 'What are your opening hours?', 'Tag für Tag, inklusive Abend- oder Wochenenddienst.', 'Day by day, including any evening or weekend cover.', 'Mo bis Fr, 8 bis 17 Uhr
Sa, 9 bis 12 Uhr
Sonntag geschlossen, Notdienst erreichbar', 'Mon to Fri, 8am to 5pm
Sat, 9am to 12pm
Closed Sunday, emergency line open', true, true, false, '[]'::jsonb, '{"rows":4}'::jsonb, '[]'::jsonb, true),
  ('service_scope', 'business', 180, 'radio', 'Wo arbeiten, verkaufen oder betreuen Sie?', 'Where do you work, sell or take clients?', null, null, null, null, true, false, false, '[{"value":"one_town","label_de":"Ein Ort oder eine Region","label_en":"One town or region"},{"value":"several","label_de":"Mehrere Regionen","label_en":"Several regions"},{"value":"national","label_de":"Bundesweit","label_en":"Nationwide"},{"value":"international","label_de":"International","label_en":"International"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('regions_served', 'business', 190, 'textarea', 'Welche Regionen bedienen Sie?', 'Which regions do you serve?', 'Bitte genau, denn das steht später in Überschriften, Menüs, der Fußzeile und in dem Text, den Google anzeigt.', 'Please be precise, because this appears in headings, menus, footers and the text Google shows.', 'München und 50 km drumherum, inklusive Dachau und Fürstenfeldbruck', 'München and 50km around it, including Dachau and Fürstenfeldbruck', true, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"service_scope","values":["one_town","several"]}]'::jsonb, true),
  ('second_address_details', 'business', 200, 'textarea', 'Besuchen Kunden noch weitere Adressen?', 'Do customers visit any other addresses?', 'Bitte frei lassen, wenn es nur eine gibt.', 'Please leave it blank if there is only one.', 'Werkstatt, Industriestraße 8, 80999 München. Nur Abholung, kein Ausstellungsraum.', 'Werkstatt, Industriestraße 8, 80999 München. Collections only, no showroom.', false, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[]'::jsonb, true),
  ('private_content', 'business', 210, 'radio', 'Gibt es etwas, das hinter ein Passwort oder einen Mitglieder-Login gehört?', 'Is there anything that should sit behind a password or a member login?', 'Bitte sagen Sie uns hier auch, was niemals öffentlich erscheinen darf, etwa Preise, Margen oder Kundennamen.', 'Please tell us here too if something must never appear publicly, such as prices, margins or named clients.', null, null, true, false, false, '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"},{"value":"unsure","label_de":"Nicht sicher","label_en":"Not sure"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('private_content_detail', 'business', 220, 'textarea', 'Was gehört dahinter und wer bekommt Zugang?', 'What should sit behind it and who gets access?', 'Mitgliederbereiche sind nicht Teil des gebuchten Pakets, wir kommen dazu separat auf Sie zu.', 'Member areas are not part of the booked package, so we will come back to you on this separately.', 'Händlerpreisliste, nur für unsere zwölf Fachkunden', 'Trade price list, for our twelve trade customers only', true, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"private_content","values":["yes"]}]'::jsonb, true),
  ('site_emails', 'inboxes', 230, 'textarea', 'Welche E-Mail-Adressen sollen auf Ihrer Seite stehen?', 'Which email addresses should appear on your site?', 'Bitte nur Adressen, die auch wirklich jemand liest.', 'Please list only addresses that someone actually reads.', 'info@mueller-sanitaer.de, allgemeine Anfragen
termine@mueller-sanitaer.de, Terminwünsche', 'info@mueller-sanitaer.de, general enquiries
termine@mueller-sanitaer.de, appointments', true, false, false, '[]'::jsonb, '{"rows":4}'::jsonb, '[]'::jsonb, true),
  ('routing_split', 'inboxes', 240, 'radio', 'Sollen verschiedene Arten von Nachrichten an verschiedene Personen gehen?', 'Should different types of message go to different people?', null, null, null, null, true, false, false, '[{"value":"yes","label_de":"Ja, bitte getrennt verteilen","label_en":"Yes, please route them separately"},{"value":"no","label_de":"Nein, bitte alles an eine Adresse","label_en":"No, please send everything to one address"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('routing_single', 'inboxes', 250, 'email', 'An welche Adresse soll alles gehen?', 'Which address should everything go to?', null, null, 'info@mueller-sanitaer.de', 'info@mueller-sanitaer.de', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"routing_split","values":["no"]}]'::jsonb, true),
  ('notification_routing', 'inboxes', 260, 'repeater', 'Wohin soll welche Art von Nachricht gehen?', 'Where should each type of message go?', 'Wir haben die Adressen übernommen, die Sie uns genannt haben. Bitte ändern Sie alles, was woandershin soll.', 'We have carried over the addresses you gave us, so please change any that should go somewhere different.', null, null, true, false, false, '[]'::jsonb, '{"min_rows":1,"max_rows":8,"initial_rows":2,"add_label_de":"Weitere hinzufügen","add_label_en":"Add another","fields":[{"key":"type","type":"text","label_de":"Art der Nachricht","label_en":"Type of message","required":true,"placeholder_de":"Allgemeine Anfrage","placeholder_en":"General enquiry"},{"key":"address","type":"email","label_de":"Geht an","label_en":"Send it to","required":true,"placeholder_de":"info@mueller-sanitaer.de","placeholder_en":"info@mueller-sanitaer.de"}]}'::jsonb, '[{"key":"routing_split","values":["yes"]}]'::jsonb, true),
  ('approver', 'inboxes', 270, 'text', 'Wer gibt die Website final frei?', 'Who gives final approval on the website?', 'Bitte ein Name: die Person, deren Ja bedeutet, dass wir live gehen können.', 'One name, please: the person whose yes means we can go live.', 'Anna Meier', 'Anna Meier', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('content_sender', 'inboxes', 280, 'text', 'Wer schickt uns Ihre Texte und Fotos?', 'Who will send us your text and photos?', null, null, 'Anna Meier', 'Anna Meier', true, false, false, '[]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('business_one_liner', 'design', 290, 'textarea', 'Was machen Sie, in einem Satz?', 'In one sentence, what do you do?', 'Bitte in den Worten, die Sie einem Kunden sagen würden, der vor Ihnen steht.', 'Please use the words you would say to a customer standing in front of you.', 'Wir sanieren Bäder, schnell und sauber, und wir werden an dem Tag fertig, den wir zugesagt haben.', 'We renovate bathrooms, quickly and cleanly and we finish on the day we said we would.', true, false, true, '[]'::jsonb, '{"rows":3,"min_chars":25,"ai_assist":true}'::jsonb, '[]'::jsonb, true),
  ('target_audience', 'design', 300, 'textarea', 'Für wen ist Ihre Website vor allem da?', 'Who is your website mainly for?', 'Bitte beschreiben Sie die Person, nicht den Markt.', 'Please describe the person rather than the market.', 'Hauseigentümer über 50, die eine große Renovierung planen, meist ihre letzte.', 'Homeowners over 50 planning one big renovation, usually their last one.', true, false, true, '[]'::jsonb, '{"rows":3,"min_chars":25,"ai_assist":true}'::jsonb, '[]'::jsonb, true),
  ('usps', 'design', 310, 'textarea', 'Warum wählen Kunden Sie und nicht die nächste Firma?', 'Why do customers choose you rather than the next firm?', 'Bitte konkret.', 'Please be concrete.', 'Festpreis, bevor wir anfangen. Dreißig Jahre in derselben Straße. Wir arbeiten nie mit Subunternehmern.', 'Fixed price agreed before we start. Thirty years in the same street. We never use subcontractors.', true, false, true, '[]'::jsonb, '{"rows":4,"min_chars":30,"ai_assist":true}'::jsonb, '[]'::jsonb, true),
  ('tagline', 'design', 320, 'textarea', 'Haben Sie einen Slogan, der auf die Seite soll?', 'Do you have a slogan or tagline you want on your site?', null, null, 'Bäder, die halten.', 'Bäder, die halten.', false, false, false, '[]'::jsonb, '{"rows":2}'::jsonb, '[]'::jsonb, true),
  ('proof_to_show', 'design', 330, 'checkboxes', 'Welche Belege sollen wir auf Ihrer Seite zeigen?', 'What proof would you like us to show on your site?', 'Bitte nur das, was Sie uns auch geben können, denn wir gestalten dafür Platz ein.', 'Please pick the ones you can actually give us, because we will design space for them.', null, null, true, false, false, '[{"value":"reviews","label_de":"Kundenbewertungen","label_en":"Customer reviews"},{"value":"years","label_de":"Jahre am Markt","label_en":"Years in business"},{"value":"certifications","label_de":"Zertifikate und Qualifikationen","label_en":"Certifications and qualifications"},{"value":"clients","label_de":"Kunden oder Partner mit Namen","label_en":"Named clients or partners"},{"value":"awards","label_de":"Auszeichnungen","label_en":"Awards"},{"value":"guarantees","label_de":"Garantien","label_en":"Guarantees"},{"value":"work_photos","label_de":"Fotos Ihrer Arbeit","label_en":"Photos of your work"},{"value":"before_after","label_de":"Vorher-nachher-Fotos","label_en":"Before and after photos"},{"value":"nothing","label_de":"Nichts davon, wir hätten es lieber schlicht","label_en":"Nothing, we would rather keep it plain"}]'::jsonb, '{"min_checked":1,"exclusive":["nothing"]}'::jsonb, '[]'::jsonb, true),
  ('factual_claims', 'design', 340, 'textarea', 'Wie lauten die Angaben und wer hat sie bestätigt?', 'What are the details and who has confirmed them?', 'Alles Sachliche auf Ihrer Seite ist eine öffentliche Aussage Ihres Unternehmens, deshalb veröffentlichen wir nur, was Sie bestätigt haben.', 'Anything factual on your site is a public statement by your company, so we only publish what you have confirmed.', 'Jahre am Markt: gegründet 1994, bestätigt von Anna
Zertifikate: Meisterbetrieb seit 2003, bestätigt von Anna', 'Years in business: founded 1994, confirmed by Anna
Certifications: Meisterbetrieb since 2003, confirmed by Anna', true, false, false, '[]'::jsonb, '{"rows":4}'::jsonb, '[{"key":"proof_to_show","values":["nothing"],"negate":true}]'::jsonb, true),
  ('tone_scale', 'design', 350, 'slider', 'Wie soll sich Ihre Seite anfühlen?', 'How should your site feel?', 'Bitte stellen Sie sich einen Ihrer Kunden vor, der die Seite öffnet, und wählen Sie, was sich für ihn richtig anfühlen würde.', 'Please picture one of your customers opening it and choose what would feel right to them.', null, null, true, false, false, '[]'::jsonb, '{"min":1,"max":5,"captions":[{"de":"Verspielt und fröhlich","en":"Fun and playful"},{"de":"Warm und ungezwungen","en":"Warm and informal"},{"de":"Freundlich, aber professionell","en":"Friendly but professional"},{"de":"Professionell und zurückhaltend","en":"Professional and restrained"},{"de":"Formell und seriös","en":"Formal and serious"}],"examples":[{"de":"Kindergarten, Kreativwerkstatt, Trampolinpark","en":"Kindergarten, art and craft studio, trampoline park"},{"de":"Friseur, Café, Personal Trainer","en":"Hairdresser, café, personal trainer"},{"de":"Die meisten Handwerksbetriebe, die meisten Praxen","en":"Most trades, most clinics"},{"de":"Beratung, Arztpraxis","en":"Consultancy, medical practice"},{"de":"Kanzlei, Steuerberatung, Behörde","en":"Law firm, accountant, government"}]}'::jsonb, '[]'::jsonb, true),
  ('personality_scale', 'design', 360, 'slider', 'Wie markant soll das Design sein?', 'How bold should the design be?', 'Hier geht es darum, wie stark das Design selbst auffällt, nicht darum, wie förmlich es ist.', 'This one is about how much the design itself stands out, not how formal it is.', null, null, true, false, false, '[]'::jsonb, '{"min":1,"max":5,"captions":[{"de":"Sehr schlicht","en":"Very plain"},{"de":"Zurückhaltend","en":"Understated"},{"de":"Ausgewogen","en":"Balanced"},{"de":"Eigenständig","en":"Distinctive"},{"de":"Markant","en":"Bold"}],"examples":[{"de":"Klare Struktur, fast keine Dekoration","en":"Clean structure, almost no decoration"},{"de":"Ruhige Farben, klassische Schrift","en":"Calm colours, classic type"},{"de":"Ein paar Akzente, ohne laut zu werden","en":"A few accents without shouting"},{"de":"Eigene Fotos, charaktervolle Schrift","en":"Your own photography, characterful type"},{"de":"Große Gesten, starke Farben","en":"Big gestures, strong colours"}]}'::jsonb, '[]'::jsonb, true),
  ('references', 'design', 370, 'repeater', 'Welche Websites gefallen Ihnen?', 'Which websites do you like?', 'Eine reicht, drei sind ideal. Bitte sagen Sie uns, welcher Teil Ihnen gefällt, nicht die ganze Seite.', 'One is enough, three is ideal. Please tell us the part you like, not the whole site.', null, null, true, false, false, '[]'::jsonb, '{"min_rows":1,"max_rows":3,"initial_rows":1,"add_label_de":"Weitere Seite hinzufügen","add_label_en":"Add another site","link_setting":"onb_examples_url","link_label_de":"Beispiele unserer Arbeit ansehen","link_label_en":"See examples of our work","fields":[{"key":"url","type":"url","label_de":"Link","label_en":"Link","required":true,"placeholder_de":"https://www.musterpraxis.de","placeholder_en":"https://www.musterpraxis.de"},{"key":"likes","type":"textarea","label_de":"Was gefällt Ihnen daran?","label_en":"What do you like about it?","required":true,"min_chars":15,"placeholder_de":"Wie die Leistungen aufgelistet sind, eine pro Karte mit Preis","placeholder_en":"The way the treatments are listed, one per card with the price"},{"key":"dislikes","type":"textarea","label_de":"Was gefällt Ihnen nicht?","label_en":"Anything you do not like?","placeholder_de":"Zu viel Blau","placeholder_en":"Too much blue"}]}'::jsonb, '[]'::jsonb, true),
  ('reference_screenshots', 'design', 380, 'upload', 'Haben Sie Screenshots oder etwas anderes, das zeigt, was Ihnen gefällt?', 'Do you have screenshots, or anything else that shows what you like?', 'Eine Broschüre, ein Schaufenster, eine Zeitschriftenseite, wirklich alles.', 'A brochure, a shop front, a magazine page, anything at all.', null, null, false, false, false, '[]'::jsonb, '{"max_files":10,"max_mb":25}'::jsonb, '[]'::jsonb, true),
  ('avoid', 'design', 390, 'textarea', 'Gibt es etwas, das Sie auf Ihrer Website nicht wollen?', 'Is there anything you do not want on your website?', 'Bitte deutlich, denn wir behandeln das als harte Regel, nicht als Vorliebe.', 'Please be blunt, because we treat this as a hard rule rather than a preference.', 'Keine Stockfotos von Menschen im Anzug. Nichts, was nach Krankenhaus aussieht. Keine Slider.', 'No stock photos of people in suits. Nothing that looks like a hospital. No sliding banners.', true, false, false, '[]'::jsonb, '{"rows":3,"none_label_de":"Mir fällt nichts ein","none_label_en":"Nothing comes to mind"}'::jsonb, '[]'::jsonb, true),
  ('brand_guidelines', 'design', 400, 'radio', 'Haben Sie ein Marken- oder Gestaltungshandbuch?', 'Do you have a brand or design guideline document?', 'Wenn ja, ersparen Sie uns das Raten, und wir halten uns daran.', 'If you have one it saves us guessing and we will follow it.', null, null, true, false, false, '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"},{"value":"unsure","label_de":"Nicht sicher","label_en":"Not sure"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
