  ('brand_colours', 'design', 420, 'text', 'Welche Farben hat Ihre Marke?', 'What are your brand colours?', 'Hex-Codes, wenn Sie sie haben, sonst bitte beschreiben.', 'Hex codes if you have them, otherwise please describe them.', 'Das Dunkelblau von unseren Transportern und ein warmes Orange. #1E5EFF, #F27127', 'The dark blue from our vans and a warm orange. #1E5EFF, #F27127', false, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"brand_guidelines","values":["yes"],"negate":true}]'::jsonb, true),
  ('colour_mood', 'design', 430, 'checkboxes', 'Welche Farbstimmung passt zu Ihrem Unternehmen?', 'What colour mood fits your business?', 'Bitte wählen Sie, wie die Farben wirken sollen. Höchstens zwei.', 'Please choose how the colours should feel in use. Up to two.', null, null, true, false, false, '[{"value":"light","label_de":"Hell und luftig","label_en":"Light and airy"},{"value":"dark","label_de":"Dunkel und hochwertig","label_en":"Dark and premium"},{"value":"warm","label_de":"Warm und erdig","label_en":"Warm and earthy"},{"value":"cool","label_de":"Kühl und klinisch","label_en":"Cool and clinical"},{"value":"bold","label_de":"Kräftig und kontrastreich","label_en":"Bold and high contrast"},{"value":"muted","label_de":"Gedeckt und ruhig","label_en":"Muted and calm"}]'::jsonb, '{"min_checked":1,"max_checked":2}'::jsonb, '[]'::jsonb, true),
  ('typography_feel', 'design', 440, 'radio', 'Welche Art von Schrift fühlt sich richtig an?', 'Which kind of lettering feels right?', 'Nicht die genaue Schriftart, nur die Familie, zu der sie gehört.', 'Not the exact font, please, just the family it belongs to.', null, null, true, true, false, '[{"value":"classic","label_de":"Klassisch und traditionell","label_en":"Classic and traditional"},{"value":"modern","label_de":"Klar und modern","label_en":"Clean and modern"},{"value":"technical","label_de":"Technisch und präzise","label_en":"Technical and precise"},{"value":"warm","label_de":"Warm und rund","label_en":"Warm and rounded"},{"value":"trust","label_de":"Entscheiden Sie, wir vertrauen Ihnen","label_en":"You choose, we trust you"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('photo_subjects', 'design', 450, 'checkboxes', 'Welche Fotos wollen Sie auf Ihrer Seite?', 'What photos do you want on your site?', 'Wir gleichen das mit den Dateien ab, die Sie uns später schicken.', 'We will check this against the files you send us later.', null, null, true, false, false, '[{"value":"work","label_de":"Unsere fertigen Arbeiten","label_en":"Our finished work"},{"value":"team","label_de":"Uns und unser Team","label_en":"Us and our team"},{"value":"premises","label_de":"Unsere Räume","label_en":"Our premises"},{"value":"products","label_de":"Unsere Produkte","label_en":"Our products"},{"value":"customers","label_de":"Menschen wie unsere Kunden","label_en":"People like our customers"},{"value":"none","label_de":"Kaum Fotos, lieber Schrift und Grafik","label_en":"Mostly no photos, type and graphics"}]'::jsonb, '{"min_checked":1,"exclusive":["none"]}'::jsonb, '[]'::jsonb, true),
