  ('homepage_density', 'design', 470, 'radio', 'Wie viel soll Ihre Startseite sagen?', 'How much should your homepage say?', 'Es gibt kein Richtig, bitte entscheiden Sie danach, ob Ihre Kunden schnell entscheiden oder sich Zeit nehmen.', 'There is no right answer, so please choose by whether your customers decide quickly or take their time.', null, null, true, false, false, '[{"value":"short","label_de":"Kurz und knackig, sie sollen anrufen","label_en":"Short and punchy, we want them to call"},{"value":"balanced","label_de":"Ausgewogen, genug zum Entscheiden","label_en":"Balanced, enough to decide"},{"value":"detailed","label_de":"Ausführlich, unsere Kunden lesen alles, bevor sie kaufen","label_en":"Detailed, our customers read everything before they buy"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
