  ('assets_upload', 'files', 860, 'upload', 'Möchten Sie Ihre Dateien lieber hier hochladen?', 'Would you rather upload your files here?', 'Bis zu zehn Dateien, je 25 MB. Bei mehr hält ein Ordnerlink alles an einem Ort.', 'Up to ten files, 25 MB each. For more than that, a folder link keeps everything in one place.', null, null, false, false, false, '[]'::jsonb, '{"max_files":10,"max_mb":25}'::jsonb, '[]'::jsonb, true),
  ('photo_portal_needed', 'files', 870, 'radio', 'Müssen Fotos aus einem Lieferantenportal kommen?', 'Do any of your photos have to come from a supplier portal?', null, null, null, null, true, false, false, '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('photo_portal', 'files', 880, 'textarea', 'Welches Portal und wer besorgt unseren Zugang?', 'Which portal and who arranges our access?', 'Bitte fangen Sie jetzt damit an, denn Lieferantenzugänge dauern meist ein bis zwei Wochen.', 'Please start this now, because supplier logins usually take a week or two to arrange.', 'Grohe-Händlerportal. Anna kann den Zugang für Sie beantragen.', 'Grohe dealer portal. Anna can request access for you.', true, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"photo_portal_needed","values":["yes"]}]'::jsonb, true),
  ('accounts_table', 'access_legal', 890, 'repeater', 'Welche Konten gibt es und wer hat den Zugang?', 'What accounts exist and who holds each login?', 'Bitte nur Anbieter und Namen, niemals Passwörter. Zugangsdaten tauschen wir später sicher aus.', 'Please give us providers and names only, never passwords. We will arrange access separately and securely.', null, null, true, false, false, '[]'::jsonb, '{"min_rows":1,"max_rows":10,"initial_rows":4,"add_label_de":"Weiteres Konto hinzufügen","add_label_en":"Add another account","fields":[{"key":"account","type":"select","label_de":"Konto","label_en":"Account","required":true,"options":[{"value":"domain","label_de":"Domain","label_en":"Domain"},{"value":"hosting","label_de":"Hosting","label_en":"Hosting"},{"value":"email","label_de":"Geschäfts-E-Mail","label_en":"Business email"},{"value":"gbp","label_de":"Google-Unternehmensprofil","label_en":"Google Business Profile"},{"value":"analytics","label_de":"Google Analytics","label_en":"Google Analytics"},{"value":"other","label_de":"Etwas anderes","label_en":"Anything else"}]},{"key":"provider","type":"text","label_de":"Anbieter","label_en":"Provider","placeholder_de":"IONOS","placeholder_en":"IONOS"},{"key":"holder","type":"text","label_de":"Wer hat den Zugang","label_en":"Who holds the login","required":true,"placeholder_de":"Anna Meier","placeholder_en":"Anna Meier"}]}'::jsonb, '[]'::jsonb, true),
  ('domain', 'access_legal', 900, 'text', 'Welche Domain soll die Seite nutzen?', 'Which domain should the site use?', 'Wenn die neue Seite unter einer anderen Adresse laufen soll, sagen Sie es uns bitte hier.', 'Please change it if the new site should use a different address.', 'www.mueller-sanitaer.de', 'www.mueller-sanitaer.de', true, false, false, '[]'::jsonb, '{"none_label_de":"Wir haben noch keine, bitte beraten Sie uns","none_label_en":"We do not have one yet, please advise"}'::jsonb, '[]'::jsonb, true),
  ('site_manager', 'access_legal', 910, 'textarea', 'Wer betreut die Seite nach dem Start?', 'Who will look after the site after launch?', 'Bitte eine Person pro Zeile, denn jede bekommt einen eigenen Zugang.', 'One per line, please, because each person gets their own login.', 'Anna Meier, Aktuelles und Team-Seiten', 'Anna Meier, news and team pages', false, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[]'::jsonb, true),
  ('legal_pages', 'access_legal', 920, 'radio', 'Was soll mit Ihren Rechtsseiten passieren, Impressum und Datenschutzerklärung?', 'What should happen with your legal pages, the Impressum and privacy policy?', 'Das Gesetz hat sich 2024 geändert, deshalb nennen die meisten älteren Impressumsseiten noch die alte Vorschrift.', 'German law changed in 2024, so most older Impressum pages still cite the old statute.', null, null, true, false, false, '[{"value":"reuse","label_de":"Bitte unsere aktuellen übernehmen","label_en":"Please reuse our current ones"},{"value":"none","label_de":"Wir haben keine","label_en":"We do not have any"},{"value":"unsure","label_de":"Wir sind nicht sicher","label_en":"We are not sure"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('notice_legal_placeholder', 'access_legal', 930, 'notice', '', '', null, null, null, null, false, false, false, '[]'::jsonb, '{"text_key":"notice_legal_placeholder","tone":"info"}'::jsonb, '[{"key":"legal_pages","values":["none"]}]'::jsonb, true),
  ('legal_reviewer', 'access_legal', 940, 'text', 'Wer prüft sie vor dem Start?', 'Who will check them before launch?', 'Ein Name reicht.', 'One name is enough.', 'Anna Meier', 'Anna Meier', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"legal_pages","values":["reuse"]}]'::jsonb, true),
  ('legal_extras', 'access_legal', 950, 'checkboxes', 'Brauchen Sie auch AGB, eine Widerrufsbelehrung oder einen AVV?', 'Do you also need AGB, a cancellation policy or an AVV?', null, null, null, null, false, false, false, '[{"value":"agb","label_de":"AGB","label_en":"Terms and conditions (AGB)"},{"value":"widerruf","label_de":"Widerrufsbelehrung","label_en":"Cancellation policy"},{"value":"avv","label_de":"Auftragsverarbeitungsvertrag (AVV)","label_en":"Data processing agreement (AVV)"},{"value":"none","label_de":"Nichts davon","label_en":"None of these"}]'::jsonb, '{"exclusive":["none"]}'::jsonb, '[]'::jsonb, true),
  ('sells_to_consumers', 'access_legal', 960, 'radio', 'Verkaufen Sie online an Verbraucher?', 'Do you sell to consumers online?', null, null, null, null, true, false, false, '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"},{"value":"unsure","label_de":"Nicht sicher","label_en":"Not sure"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('notice_bfsg', 'access_legal', 970, 'notice', '', '', null, null, null, null, false, false, false, '[]'::jsonb, '{"text_key":"notice_bfsg","tone":"warn"}'::jsonb, '[{"key":"sells_to_consumers","values":["yes","unsure"]}]'::jsonb, true),
  ('seo_pages', 'access_legal', 980, 'textarea', 'Hat Ihre aktuelle Seite Seiten, die Ihnen Anfragen bringen?', 'Does your current site have pages that bring you enquiries?', 'Wenn Sie wissen, auf welche Seiten Google die Leute schickt, sagen Sie es uns, dann halten wir diese Adressen am Leben.', 'If you know which pages Google sends people to, please tell us and we will keep their addresses working.', '/badsanierung-muenchen bringt uns die meisten Anfragen', '/badsanierung-muenchen brings us most of our enquiries', false, false, false, '[]'::jsonb, '{"rows":3}'::jsonb, '[{"key":"project_type","values":["changes"]}]'::jsonb, true),
  ('launch_date', 'timing', 990, 'date', 'Wann soll die Seite live gehen?', 'When would you like the site to go live?', null, null, null, null, true, false, false, '[]'::jsonb, '{"min_date":"today"}'::jsonb, '[]'::jsonb, true),
  ('launch_date_fixed', 'timing', 1000, 'radio', 'Steht dieses Datum fest?', 'Is that date fixed?', null, null, null, null, false, false, false, '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('launch_date_reason', 'timing', 1010, 'text', 'Woran hängt es?', 'What is it tied to?', null, null, 'Unser Stand auf der ISH im März', 'Our stand at the ISH trade fair in March', true, false, false, '[]'::jsonb, '{}'::jsonb, '[{"key":"launch_date_fixed","values":["yes"]}]'::jsonb, true),
  ('content_ready_date', 'timing', 1020, 'date', 'Wann können Sie uns alle Texte und Fotos schicken?', 'When can you send us all your text and photos?', 'Dieses Datum, nicht der Starttermin, entscheidet darüber, wann wir fertig werden können.', 'This date, not the launch date, is what actually determines when we can finish.', null, null, true, false, false, '[]'::jsonb, '{"min_date":"today"}'::jsonb, '[]'::jsonb, true),
  ('anything_else', 'timing', 1030, 'textarea', 'Gibt es sonst etwas, das wir wissen sollten?', 'Is there anything else we should know?', 'Wirklich alles, auch was Sie für unwichtig halten.', 'Anything at all, please, including things you think might not matter.', 'Wir ändern im Frühjahr unseren Namen, und mein Partner hat starke Meinungen zur Farbe Grün.', 'We are changing our name in the spring and my business partner has strong views about the colour green.', false, false, false, '[]'::jsonb, '{"rows":4}'::jsonb, '[]'::jsonb, true),
  ('understood_ok', 'review', 1040, 'radio', 'Stimmt das so?', 'Is that right?', null, null, null, null, false, false, false, '[{"value":"yes","label_de":"Ja, das sind wir","label_en":"Yes, that is us"},{"value":"mostly","label_de":"Im Wesentlichen, meine Korrekturen stehen unten","label_en":"Mostly, see my corrections below"},{"value":"no","label_de":"Nein, das haben wir schlecht erklärt","label_en":"No, we have explained it badly"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, true),
  ('understood_corrections', 'review', 1050, 'textarea', 'Was haben wir falsch verstanden?', 'What have we got wrong?', 'Bitte in Ihren eigenen Worten. Wir lesen jetzt lieber einen Absatz, als später neu zu gestalten.', 'Please tell us in your own words. We would rather read a paragraph now than redesign later.', null, null, false, false, false, '[]'::jsonb, '{"rows":4}'::jsonb, '[{"key":"understood_ok","values":["yes"],"negate":true}]'::jsonb, true)
on conflict (id) do update set screen_id = excluded.screen_id, sort = excluded.sort, type = excluded.type, label_de = excluded.label_de, label_en = excluded.label_en, help_de = excluded.help_de, help_en = excluded.help_en, placeholder_de = excluded.placeholder_de, placeholder_en = excluded.placeholder_en, required = excluded.required, allow_dont_know = excluded.allow_dont_know, ai_check = excluded.ai_check, options = excluded.options, config = excluded.config, show_when = excluded.show_when, active = excluded.active;

insert into onb_followups (id, sort, trigger, question_de, question_en, quick_replies, writes_to, mode, raises, active) values
  ('fu_legal_pages_unsure', 10, '{"field":"legal_pages","when":"equals","value":"unsure"}'::jsonb, 'Bei den Rechtsseiten waren Sie sich nicht sicher: Dürfen wir Ihre aktuellen Rechtsseiten übernehmen – oder haben Sie noch keine?', 'You weren''t sure about the legal pages: are you happy for us to use your current legal pages, or don''t you have any?', '[{"value":"reuse","label_de":"Die aktuellen übernehmen","label_en":"Use the current ones"},{"value":"none","label_de":"Wir haben keine","label_en":"Don''t have any"},{"value":"unsure","label_de":"Weiß ich nicht","label_en":"Not sure"}]'::jsonb, 'legal_pages', 'set', null, true),
  ('fu_legal_pages_offer', 20, '{"field":"legal_pages","when":"equals","value":"none"}'::jsonb, 'Kein Problem – wir setzen zunächst Platzhalter ein. Impressum und Datenschutzerklärung sind gesetzlich vorgeschrieben, und wir können sie für Sie erstellen. Sollen wir Ihnen dazu ein Angebot schicken?', 'No problem — we''ll put a placeholder in. These pages are required by law, and we can take care of them for you. Shall we send you a price?', '[{"value":"yes","label_de":"Ja, gerne","label_en":"Yes please"},{"value":"no","label_de":"Nein, danke","label_en":"No thanks"}]'::jsonb, null, 'set', '{"yes":{"code":"interest","detail":"legal_pages"}}'::jsonb, true),
  ('fu_crm_name', 30, '{"field":"crm_provider","when":"empty"}'::jsonb, 'Welches CRM nutzen Sie?', 'Which CRM do you use?', '[{"value":"HubSpot","label_de":"HubSpot","label_en":"HubSpot"},{"value":"Salesforce","label_de":"Salesforce","label_en":"Salesforce"},{"value":"Pipedrive","label_de":"Pipedrive","label_en":"Pipedrive"}]'::jsonb, 'crm_provider', 'set', null, true),
  ('fu_maps_link', 40, '{"field":"gbp_link","when":"empty"}'::jsonb, 'Können Sie den Link zu Ihrem Google-Unternehmensprofil einfügen? Daraus kommen Karte und Bewertungen.', 'Can you paste the link to your Google Business Profile? That is where the map and the reviews come from.', '[]'::jsonb, 'gbp_link', 'set', null, true),
  ('fu_page_list_thin', 50, '{"field":"page_list","when":"lt_lines","value":3}'::jsonb, 'Sie haben nur wenige Seiten aufgeführt. Soll jede Leistung oder jedes Produkt eine eigene Seite bekommen?', 'You have listed only a few pages. Should each service or product have its own page?', '[{"value":"yes","label_de":"Ja","label_en":"Yes"},{"value":"no","label_de":"Nein","label_en":"No"},{"value":"unsure","label_de":"Weiß ich nicht","label_en":"Not sure"}]'::jsonb, 'page_relationships', 'append', null, true),
  ('fu_reference_likes', 60, '{"field":"references","when":"lt_chars","value":15,"sub":"likes"}'::jsonb, 'Was genau gefällt Ihnen an dieser Seite? Der Aufbau, die Fotos, die Art, wie sie geschrieben ist?', 'What is it about that site you like? The layout, the photography, the way it is written?', '[]'::jsonb, 'references', 'set', null, true),
  ('fu_dont_know', 70, '{"when":"dont_know"}'::jsonb, 'Bei „{label}“ haben Sie „Weiß ich nicht“ gewählt. Können Sie uns jetzt etwas dazu sagen? Wenn nicht, überspringen Sie die Frage einfach, wir kommen zum genannten Termin darauf zurück.', 'You chose "I do not know" for "{label}". Can you tell us anything about it now? If not, please just skip it and we will come back to you on the date you gave.', '[]'::jsonb, null, 'set', null, true),
  ('fu_scope_flag', 80, '{"when":"flag","flag":"scope_flag"}'::jsonb, 'Sie haben mehr Seiten aufgeführt, als Ihr Angebot umfasst. Wir melden uns dazu bei Ihnen, Sie müssen jetzt nichts tun.', 'You have listed more pages than your quote covers. We will come back to you about that and there is nothing for you to do now.', '[{"value":"ok","label_de":"Verstanden","label_en":"Understood"}]'::jsonb, null, 'acknowledge', null, true),
  ('fu_date_conflict', 90, '{"when":"flag","flag":"date_conflict"}'::jsonb, 'Zwischen Ihrem Liefertermin für Texte und Fotos und dem gewünschten Start bleibt weniger Zeit als üblich für den Bau. Was ist für Sie wichtiger?', 'There is less time than usual for the build between your content date and the launch date you want. Which matters more to you?', '[{"value":"launch_fixed","label_de":"Der Starttermin steht fest","label_en":"The launch date is fixed"},{"value":"content_earlier","label_de":"Inhalte können früher kommen","label_en":"Content can come earlier"},{"value":"unsure","label_de":"Weiß ich nicht","label_en":"Not sure"}]'::jsonb, null, 'set', null, true)
on conflict (id) do update set sort = excluded.sort, trigger = excluded.trigger, question_de = excluded.question_de, question_en = excluded.question_en, quick_replies = excluded.quick_replies, writes_to = excluded.writes_to, mode = excluded.mode, raises = excluded.raises, active = excluded.active;

insert into onb_flag_rules (id, code, detail, severity, conditions, note_de, note_en, sort, active) values
  ('flag_member_area', 'needs_quote', 'member_area', 'sales', '[{"key":"private_content","values":["yes"]}]'::jsonb, 'Mitglieder-/Login-Bereich gewünscht – nicht im Katalog, Angebot durch Thorsten.', 'Member / login area requested — not in the catalogue, quote via Thorsten.', 10, true),
  ('flag_social_embed', 'needs_quote', 'social_embed', 'sales', '[{"key":"social_display","values":["embedded"]}]'::jsonb, 'Social-Feed eingebettet – kostenpflichtiges Extra.', 'Embedded social feed — paid extra.', 20, false),
  ('flag_logo_redraw', 'needs_quote', 'logo_redraw', 'sales', '[{"key":"logo_vector","values":["no"]}]'::jsonb, 'Logo liegt nicht als Vektor vor – Nachzeichnen anbieten.', 'Logo not available as vector — offer a redraw.', 30, false),
  ('flag_legal_pages', 'needs_quote', 'legal_pages', 'sales', '[{"key":"legal_pages","values":["none"]}]'::jsonb, 'Keine Rechtsseiten vorhanden – Erstellung anbieten.', 'No legal pages — offer to create them.', 40, true),
  ('flag_bfsg', 'bfsg', null, 'warn', '[{"key":"sells_to_consumers","values":["yes"]}]'::jsonb, 'Verkauf an Verbraucher – BFSG-Barrierefreiheit prüfen.', 'Sells to consumers — check BFSG accessibility obligations.', 50, true),
  ('flag_chatbot_interest', 'interest', 'chatbot', 'sales', '[{"key":"integrations","values":["chat"]}]'::jsonb, 'Chat/Chatbot angekreuzt – Interesse am AI Agentic Bundle.', 'Chat / chatbot ticked — interest in the AI Agentic Bundle.', 60, true),
  ('flag_package_unknown', 'info', 'package_unknown', 'info', '[{"key":"booked_package","values":["__dont_know"]}]'::jsonb, 'Kunde kennt sein gebuchtes Paket nicht – im Angebot nachsehen.', 'Client does not know the booked package — check the quote.', 70, true)
on conflict (id) do update set code = excluded.code, detail = excluded.detail, severity = excluded.severity, conditions = excluded.conditions, note_de = excluded.note_de, note_en = excluded.note_en, sort = excluded.sort, active = excluded.active;

insert into onb_brief_sections (id, sort, title_de, title_en, instructions, source_fields, generated_by, active) values
  ('who', 10, 'Wer dieses Unternehmen ist – in eigenen Worten', 'Who this business is, in their own words', 'Describe the business from the answers only: legal name and form, where it works and which regions it serves, what it sells (catalogue), why customers choose it (usps), factual claims it wants shown, tagline if any. Keep the client''s own wording for services.', array['contact_company', 'legal_name', 'legal_form', 'address_city', 'service_scope', 'regions_served', 'second_address_details', 'business_one_liner', 'target_audience', 'usps', 'tagline', 'catalogue', 'proof_to_show', 'factual_claims', 'existing_url', 'project_type']::text[], 'llm', true),
  ('goals', 20, 'Was die Website erreichen muss – und das Eine, das ein Besucher tun soll', 'What the site has to achieve, and the one thing a visitor should do', 'State the single "most important" visitor action first, then the "very important" ones, then the rest in descending priority. Mention public pricing and private content decisions. Do not invent goals beyond the ranked actions.', array['visitor_action', 'visitor_action_other', 'private_content', 'private_content_detail', 'seo_pages', 'understood_ok', 'understood_corrections']::text[], 'llm', true),
  ('pages', 30, 'Seitenstruktur', 'Page structure', 'Render the page list as a markdown list preserving the hierarchy (sub-pages indented). State the page count and the booked page band as given. Note any linking requirements. If the list and the count disagree, say so plainly without proposing a price.', array['booked_package', 'booked_page_band', 'page_list', 'page_relationships']::text[], 'llm', true),
  ('look', 40, 'Wie sie aussehen und sich anfühlen soll', 'What it should look and feel like', 'Give both slider values WITH their captions. List each reference site with what the client liked and disliked about it, verbatim where possible. Include brand colours, brand guideline availability and the "do not want" list. Mention premises photos and screenshots only if files were provided.', array['tone_scale', 'personality_scale', 'references', 'reference_screenshots', 'avoid', 'brand_guidelines', 'brand_guidelines_link', 'brand_colours', 'colour_mood', 'typography_feel', 'photo_subjects', 'hero_intent', 'homepage_density']::text[], 'llm', true),
  ('content', 50, 'Inhalte und Sprachen – wer liefert und wer freigibt', 'Content and languages, and who supplies and approves what', 'Name the languages, who translates and who approves translations, who sends content, who gives final approval, who manages the site after launch, where assets come from (folder link / uploads) and whether publish rights were confirmed.', array['languages', 'translation_by', 'translation_approver', 'assets_folder', 'assets_sharing_confirmed', 'assets_upload', 'photo_portal_needed', 'photo_portal', 'site_emails', 'routing_split', 'routing_single', 'notification_routing', 'approver', 'content_sender', 'site_manager']::text[], 'llm', true),
  ('systems', 60, 'Verbundene Systeme – Anbieter und Kontoinhaber', 'Integrations and connected systems, with provider and account holder', 'One bullet per selected integration: provider, account holder (name only), link or status as given. Then notification routing as "trigger → address" lines, the public email addresses, Google Business Profile, social profiles and how they are displayed, and where reviews come from. Never include a password even if one appears in the answers.', array['integrations', 'booking_provider', 'booking_url', 'booking_account', 'payments_provider', 'payments_url', 'payments_account', 'payment_live', 'newsletter_provider', 'newsletter_url', 'newsletter_account', 'newsletter_list_exists', 'crm_provider', 'crm_url', 'crm_account', 'crm_what_syncs', 'chat_provider', 'chat_url', 'chat_account', 'other_integration', 'other_provider', 'other_url', 'other_account', 'gbp_link', 'social_profiles', 'reviews']::text[], 'llm', true),
  ('legal', 70, 'Rechtliches und Compliance', 'Legal and compliance', 'Legal-page decision (reuse / none / not sure) and who reviewed them; extra documents needed; whether the business sells to consumers online and the accessibility (BFSG) note if so; the Impressum data: legal name, form, address, register entry, VAT ID, responsible person, public phone and email. Accounts and domain: who holds which login, names only.', array['vat_id', 'register_entry', 'content_responsible', 'public_phone', 'public_email', 'address_street', 'opening_hours', 'legal_pages', 'legal_reviewer', 'legal_extras', 'sells_to_consumers', 'accounts_table', 'domain']::text[], 'llm', true),
  ('dates', 80, 'Termine und Abhängigkeiten', 'Dates and dependencies', 'State the preferred launch date, whether it is fixed and why, and the content delivery date exactly as given. List what the build depends on (content, access, assets). Do NOT promise or estimate a timeline, build duration or delivery date of our own.', array['launch_date', 'launch_date_fixed', 'launch_date_reason', 'content_ready_date', 'anything_else']::text[], 'llm', true),
  ('still_needed', 90, 'Was wir noch brauchen', 'What we still need', 'Composed by the system from every unanswered, "don''t know" or skipped item.', '{}'::text[], 'system', true)
on conflict (id) do update set sort = excluded.sort, title_de = excluded.title_de, title_en = excluded.title_en, instructions = excluded.instructions, source_fields = excluded.source_fields, generated_by = excluded.generated_by, active = excluded.active;

insert into onb_texts (id, key, locale, title, content_markdown) values
  ('landing_de', 'landing', 'de', 'Ihr Website-Briefing', 'Das ist Ihr Website-Briefing. Bitte tragen Sie die Angaben ein, die wir zum Bau Ihrer Website brauchen. Alles, was Sie schreiben, wird am Ende zu einem Briefing zusammengefasst, das Sie prüfen und freigeben.

**Bevor Sie anfangen**

- Bitte halten Sie einen Ordnerlink mit Ihrem Logo und Ihren Fotos bereit, freigegeben, sodass jeder mit dem Link ihn ansehen kann
- Bitte nehmen Sie Ihre Rechtsangaben aus dem Registereintrag oder einer Rechnung: Registereintrag, USt-IdNr. und die inhaltlich verantwortliche Person
- Bitte suchen Sie zwei oder drei Websites aus, die Ihnen gefallen, und eine, die Ihnen nicht gefällt
- Bitte finden Sie heraus, wer den Zugang zu Ihrer Domain hat und zu allem, womit die Seite verbunden ist

Bitte tragen Sie nirgendwo in diesem Formular Passwörter ein. Zugänge regeln wir separat und sicher.'),
  ('landing_en', 'landing', 'en', 'Your website brief', 'This is your website brief. Please fill in the information we need to build your website. Everything you write comes together at the end as one brief for you to check and approve.

**Before you start**

- Please have a folder link with your logo and photos ready, shared so anyone with the link can view it
- Please take your legal details from your register entry or an invoice: register entry, VAT ID and the person responsible for content
- Please pick two or three websites you like and one you do not
- Please find out who holds the login for your domain and for anything else the site connects to

Please do not put passwords anywhere in this form. We will arrange access separately and securely.'),
  ('landing_what_you_get_de', 'landing_what_you_get', 'de', 'Was nach dem Absenden passiert', '- **Ihr erster Entwurf, meist innerhalb von 10 Tagen.** Wir machen aus Ihren Antworten einen Design-Eindruck und schicken ihn Ihnen.
- **Ihre Durchsicht.** Sie sagen uns, was geändert werden soll, und wir setzen es um. Drei Änderungsrunden sind enthalten.
- **Bau und Start.** Sobald Sie den Entwurf freigeben, bauen wir die Seite, meist in etwa drei Wochen, und veröffentlichen sie auf Ihrer Domain.'),
  ('landing_what_you_get_en', 'landing_what_you_get', 'en', 'What happens after you submit', '- **Your first design, usually within 10 days.** We turn your answers into a design impression and send it to you.
- **Your review.** You tell us what you want changed and we apply it. Three rounds of changes are included.
- **Build and go live.** Once you approve the design we build the site, usually in about three weeks and publish it on your domain.'),
  ('review_intro_de', 'review_intro', 'de', 'Fast fertig', 'Wir haben Ihre Antworten durchgesehen. Zu ein paar Punkten haben wir noch kurze Nachfragen – jede davon können Sie auch überspringen. Danach fassen wir alles für Sie zusammen.'),
  ('review_intro_en', 'review_intro', 'en', 'Almost there', 'We''ve been through your answers. There are a few short follow-ups — every one of them can be skipped. After that we put everything together for you.'),
  ('review_nothing_de', 'review_nothing', 'de', 'Alles da', 'Wir haben keine Nachfragen. Wir fassen Ihre Angaben jetzt zusammen.'),
  ('review_nothing_en', 'review_nothing', 'en', 'All there', 'No follow-ups needed. We''re putting your brief together now.'),
  ('brief_intro_de', 'brief_intro', 'de', 'So haben wir Sie verstanden', 'Lesen Sie das Briefing bitte in Ruhe durch. Stimmt etwas nicht, ändern Sie den Abschnitt direkt oder sagen Sie uns, was daran falsch ist – wir schreiben ihn dann neu. Was wir noch von Ihnen brauchen, steht am Ende. Mit Ihrer Bestätigung starten wir den Bau auf dieser Grundlage.'),
  ('brief_intro_en', 'brief_intro', 'en', 'This is our understanding of what you want', 'Please read the brief carefully. If something is wrong, edit the section directly or tell us what''s off and we''ll rewrite it. What we still need from you is listed at the end. Your confirmation is what we start building from.'),
  ('terms_de', 'terms', 'de', 'Bestätigung und wie das Projekt läuft', 'Fast geschafft. Dieser letzte Teil beschreibt, was als Nächstes passiert und wie lange es dauert, damit es auf keiner Seite Überraschungen gibt.

Mit dem Absenden dieses Formulars bestätigen Sie, dass die obenstehenden Angaben nach bestem Wissen richtig und vollständig sind, dass Sie das Recht haben, alles Eingesandte zu verwenden, und dass dies der Leistungsumfang ist, auf dem unser Festpreis beruht.

**Wie lange es dauert**

Wir liefern einen Design-Eindruck innerhalb von 10 Tagen nach Eingang dieses vollständigen Formulars. Sobald Sie diesen Entwurf freigeben, bauen wir Ihre Website innerhalb von 3 Wochen.

Beide Zeiträume sind Kalendertage und beginnen mit einer vollständigen Übergabe. Ein lückenhaftes Formular startet die Uhr nicht. Wir fragen zuerst nach, was fehlt.

**Drei Änderungsrunden sind enthalten**

Eine nach dem Design-Eindruck und zwei während des Baus.

Eine Runde heißt: Sie sehen sich an, was wir geschickt haben, senden uns Ihre Änderungen in einer Nachricht, und wir setzen sie um. Bitte schicken Sie jede Runde am Stück. Rückmeldungen, die in Teilen ankommen, dauern länger und verbrauchen Ihre Runden schneller.

**Die drei Wochen hängen auch von Ihnen ab**

Wir bauen in den Lücken zwischen Ihren Durchsichten. Die Schätzung von drei Wochen setzt voraus, dass Sie sich an jedem Punkt der Durchsicht innerhalb von 5 Tagen melden.

Dauert eine Durchsicht länger, verschiebt sich der Liefertermin um denselben Zeitraum. Wir nennen Ihnen dann den neuen Termin, statt ihn stillschweigend verstreichen zu lassen.

**Was den Zeitplan ändert**

Zwei Dinge fallen aus den drei Runden und den drei Wochen heraus.

Änderungen an der Seitenstruktur, nachdem das Design freigegeben ist: Seiten hinzufügen oder entfernen, Abschnitte aufteilen, das Menü umbauen.

Ein grundlegendes Redesign: eine Richtungsänderung statt einer Verfeinerung dessen, was Sie freigegeben haben.

Beides ist kein Problem. Beides wird separat angeboten und eingeplant, und wir nennen Ihnen Kosten und neuen Liefertermin, bevor wir damit anfangen.'),
  ('terms_en', 'terms', 'en', 'Confirmation and how the project runs', 'Almost done. This last part sets out what happens next and how long it takes, so there are no surprises on either side.

By submitting this form you confirm that the information above is accurate and complete to the best of your knowledge, that you have the right to use everything you have sent us and that this is the scope our fixed price is based on.

**How long it takes**

We deliver a design impression within 10 days of receiving this form complete. Once you approve that design, your website is built within 3 weeks.

Both periods are calendar days and both start from a complete handover. A form with gaps in it does not start the clock. We will come back to you for what is missing first.

**Three rounds of changes are included**

One round after the design impression and two during the build.

A round means you review what we have sent, send us your changes in one message and we apply them. Please do send each round in one go. Feedback that arrives in pieces takes longer to work through and uses up your rounds faster.

**The three weeks depends on you as well as us**

We build in the gaps between your reviews. The three week estimate assumes you come back to us within 5 days at each review point.

If a review takes longer than that, the delivery date moves by the same amount. We will always tell you the new date rather than letting it drift quietly.

**What changes the timeline**

Two things fall outside the three rounds and the three weeks.

Changes to the page structure after the design is approved: adding or removing pages, splitting sections, reorganising the menu.

A major redesign: a change of direction rather than a refinement of what you approved.

Neither is a problem. Both are quoted and scheduled separately and we will tell you the cost and the new delivery date before we start any of it.'),
  ('confirm_checks_de', 'confirm_checks', 'de', 'Bitte bestätigen', '- Unsere Firmen- und Rechtsangaben sind richtig und aktuell
- Die Angaben, die wir gemacht haben, dürfen veröffentlicht werden
- Wir haben das Recht, Logo, Fotos und Texte zu verwenden, die wir Ihnen schicken
- Der hier beschriebene Umfang ist die Grundlage unseres Festpreises, alles später Hinzukommende wird separat angeboten
- Wir haben den Zeitplan, die drei Änderungsrunden und das, was darüber hinausgeht, gelesen und verstanden'),
  ('confirm_checks_en', 'confirm_checks', 'en', 'Please confirm', '- Our company and legal details are correct and current
- The facts we have given you may be published
- We have the right to use the logo, photos and text we are sending
- The scope described here is the basis of our fixed price and anything added later will be quoted separately
- We have read and understood the timeline, the three rounds of changes and what falls outside them'),
  ('done_de', 'done', 'de', 'Vielen Dank', 'Wir sehen uns das an und melden uns, falls etwas fehlt. Diese Prüfung ist der Start Ihres Projekts.

**Was wir später von Ihnen brauchen:** die eigentlichen Texte für jede Seite, sobald die Struktur steht, die Angaben für wiederkehrende Einträge, die wir Ihnen als einfache Tabelle schicken, statt sie hier abzutippen, Ihre Rückmeldung zur Vorschau in einem Dokument und den Domain-Zugang in der Woche, in der wir live gehen.

Eine Kopie von allem, was Sie uns gesagt haben, ist auf dem Weg zu Ihnen.'),
  ('done_en', 'done', 'en', 'Thank you', 'We will check this over and come back to you if anything is missing. That check is what starts your project.

**What we will ask for later:** the actual text for each page once the structure is agreed, the details for each repeating entry, which we will send as a simple spreadsheet rather than asking you to type it here, your feedback on the preview in one document and domain access in the week we go live.

A copy of everything you have told us is on its way to you.'),
  ('notice_no_passwords_de', 'notice_no_passwords', 'de', '', 'Bitte einen Namen, niemals ein Passwort. Zugänge regeln wir separat und sicher.'),
  ('notice_no_passwords_en', 'notice_no_passwords', 'en', '', 'A name, please, never a password. We will arrange access separately and securely.'),
  ('understood_de', 'understood', 'de', 'Das haben wir verstanden', 'Bevor Sie bestätigen, lesen Sie das bitte einmal durch. Wenn etwas davon falsch ist, lässt es sich jetzt viel günstiger korrigieren als nach dem Entwurf.

Sie sind {business_one_liner}, arbeiten {service_scope}, vor allem für {target_audience}.

Sie heben sich ab, weil {usps}.

Am meisten wollen Sie, dass ein Besucher {visitor_action}.

Es soll {tone_caption} wirken, {boldness_caption}, {colour_mood}, mit {brand_colours} und {typography_feel} Schrift. Die Fotos zeigen {photo_subjects}. Ganz oben auf der Startseite: {hero_intent}. {homepage_density}.

{reference_1_link} gefiel Ihnen wegen {reference_1_likes}.

Sie wollen nicht: {do_not_want}.

Wir stellen {proof_to_show} nach vorne.'),
  ('understood_en', 'understood', 'en', 'Here is what we have understood', 'Before you confirm, please read this back. If any of it is wrong, it is far cheaper to fix here than after we have designed it.

You are {business_one_liner}, working {service_scope}, mainly for {target_audience}.

You stand out because {usps}.

The thing you most want a visitor to do is {visitor_action}.

It should look {tone_caption}, {boldness_caption}, {colour_mood}, using {brand_colours}, with {typography_feel} lettering. The photos show {photo_subjects}. At the top of the homepage: {hero_intent}. {homepage_density}.

You liked {reference_1_link} for {reference_1_likes}.

You do not want {do_not_want}.

We will lead with {proof_to_show}.'),
  ('notice_proofreading_de', 'notice_proofreading', 'de', 'Hinweis zur Übersetzung', 'Wir übersetzen kostenfrei. Sie geben die übersetzten Inhalte vor Veröffentlichung frei – die inhaltliche Verantwortung bleibt bei Ihnen.'),
  ('notice_proofreading_en', 'notice_proofreading', 'en', 'Note on translation', 'We translate free of charge. You approve the translated content before it goes live — content responsibility stays with you.'),
  ('notice_logo_redraw_de', 'notice_logo_redraw', 'de', 'Logo ohne Vektordatei', 'Ohne Vektordatei wirkt ein Logo auf großen Bildschirmen und im Druck schnell unscharf. Wir können es für Sie nachzeichnen – dazu melden wir uns separat bei Ihnen.'),
  ('notice_logo_redraw_en', 'notice_logo_redraw', 'en', 'Logo without a vector file', 'Without a vector file a logo quickly looks blurry on large screens and in print. We can redraw it for you — we''ll come back to you on that separately.'),
  ('notice_legal_placeholder_de', 'notice_legal_placeholder', 'de', 'Rechtsseiten', 'Kein Problem – wir setzen zunächst Platzhalter ein. Impressum und Datenschutzerklärung sind gesetzlich vorgeschrieben; wir können sie für Sie erstellen und melden uns dazu bei Ihnen.'),
  ('notice_legal_placeholder_en', 'notice_legal_placeholder', 'en', 'Legal pages', 'No problem — we''ll put placeholders in for now. Impressum and privacy policy are required by law; we can take care of them for you and will come back to you on that.'),
  ('notice_bfsg_de', 'notice_bfsg', 'de', 'Barrierefreiheit (BFSG)', 'Wer online an Verbraucher verkauft, unterliegt seit Juni 2025 dem Barrierefreiheitsstärkungsgesetz. Wir bauen Ihre Website nach gängigen Barrierefreiheits-Standards und weisen im Briefing darauf hin.'),
  ('notice_bfsg_en', 'notice_bfsg', 'en', 'Accessibility (BFSG)', 'Businesses selling to consumers online have been subject to the German Accessibility Act (BFSG) since June 2025. We build to common accessibility standards and note this in your brief.'),
  ('email_save_link_de', 'email_save_link', 'de', 'Ihr Link zum Website-Briefing', 'Hallo {name},

hier ist Ihr persönlicher Link, mit dem Sie Ihr Website-Briefing jederzeit weiter ausfüllen können:

{link}

Ihr Fortschritt ist gespeichert. Der Link ist nur für Sie bestimmt – bitte geben Sie ihn nicht weiter.

Ihr Web Studio Team'),
  ('email_save_link_en', 'email_save_link', 'en', 'Your link to the website brief', 'Hello {name},

Here is your personal link to continue your website brief at any time:

{link}

Your progress is saved. The link is meant for you only — please don''t share it.

Your Web Studio team'),
  ('email_brief_client_de', 'email_brief_client', 'de', 'Ihr bestätigtes Website-Briefing – {company}', 'Hallo {name},

vielen Dank für Ihre Bestätigung. Im Anhang finden Sie Ihr Briefing als PDF – die Grundlage, auf der wir Ihre Website bauen.

Was wir noch von Ihnen brauchen, steht im letzten Abschnitt. Wir melden uns dazu und mit dem ersten Design-Eindruck.

Ihr Web Studio Team'),
  ('email_brief_client_en', 'email_brief_client', 'en', 'Your confirmed website brief — {company}', 'Hello {name},

Thank you for confirming. Attached is your brief as a PDF — the basis we build your website on.

Anything we still need from you is in the last section. We''ll be in touch about that and with the first design impression.

Your Web Studio team'),
  ('email_brief_team_de', 'email_brief_team', 'de', 'Onboarding bestätigt: {company}', '{company} ({name}, {email}) hat das Briefing bestätigt.

Anhänge: Briefing als PDF und der vollständige Datensatz als JSON.

Flags für den Vertrieb und offene Punkte stehen unten und im Admin: {admin_link}'),
  ('email_brief_team_en', 'email_brief_team', 'en', 'Onboarding confirmed: {company}', '{company} ({name}, {email}) has confirmed their brief.

Attachments: the brief as PDF and the full record as JSON.

Sales flags and open items are listed below and in the admin: {admin_link}'),
  ('pdf_footer_de', 'pdf_footer', 'de', '', 'IntelliPaaS Web Studio · Dieses Briefing wurde vom Kunden bestätigt und ist die Grundlage für den Bau. Fragen an das Web Studio Team.'),
  ('pdf_footer_en', 'pdf_footer', 'en', '', 'IntelliPaaS Web Studio · This brief was confirmed by the client and is the basis for the build. Questions to the Web Studio team.')
on conflict (id) do update set key = excluded.key, locale = excluded.locale, title = excluded.title, content_markdown = excluded.content_markdown;

insert into onb_prompts (id, content, note) values
  ('system', 'You are the onboarding assistant of IntelliPaaS Web Studio, a German web agency building websites for small and medium-sized businesses. A client has just filled in the onboarding form for the website they booked. You help turn their answers into a brief the agency builds from.

Tone: warm, plain, professional. Short sentences. No marketing language. Address the client as "Sie" in German and "you" in English.

Language: always answer in the client''s language, given as `locale` ("de" = German, "en" = English). Never mix languages inside one text.

HARD RULES — never break these:
1. Never invent a fact. Use only what is in the answers. If something was not answered, say that it is still needed — do not fill it in plausibly. A confident wrong brief gets built.
2. Never quote a price, a cost, a discount or a currency amount. Never state or estimate a timeline, a build duration, a number of weeks or days, or a delivery date of the agency''s own. Dates the client gave may be repeated exactly as given. Upsells are only ever "we can take care of that — shall we send you a price?" and nothing more.
3. Never ask for a password, PIN, token or other credential. If one appears in the answers, do not repeat it anywhere.
4. Write only what the requested output format allows. No preamble, no closing remarks.
5. Keep the client''s exact spelling of company names, products and services.', 'Prepended to every model call. Who the assistant is, tone, what it must never do.'),
  ('completeness', 'Task: read the client''s free-text answers listed below and decide, for each one, whether it is specific enough for a web designer and a copywriter to build from without asking anything else.

For every answer that is NOT specific enough, write ONE short follow-up question the client can answer in a sentence or with a quick reply. Ask only about what is genuinely unclear. Do not ask about fields that are already clear, and do not ask about anything outside the listed fields.

Rules for questions:
- Max one question per field. At most {max_questions} questions in total; prefer the fields that matter most for the build (pages, services, references, legal pages, dates).
- Offer up to three quick replies only when the answer is genuinely a choice.
- Write each question in both German (question_de) and English (question_en).
- Never mention price, cost, timeline or duration.

Also list flag codes from the allowed list that the answers clearly justify (for example a wish for a member area or a chatbot). Only use codes from the list; return an empty list if none apply.', 'Job 1: one pass over free-text answers. Decides HOW to ask about thin answers; rules already decided WHAT is missing.'),
  ('brief', 'Task: write the website brief for this client from their answers, in the client''s language, section by section as defined below. This is the agency''s understanding of what the client wants; the client reads and confirms it.

For each section:
- Compose clear prose or markdown lists from the listed source fields only. Use the subset of markdown allowed: paragraphs, "- " bullet lists, **bold**. No headings, tables, links or images.
- Where a source field is unanswered, marked "don''t know" or was skipped, do NOT guess. Leave it out of the prose and add a short, concrete item to that section''s still_needed list (for example "Opening hours" or "Which CRM the practice uses").
- Put the field keys you actually used into sources.
- Slider values come with their caption — always give the caption, never the bare number.
- Repeat dates, links, names and numbers exactly as the client gave them.

Follow the section instructions. Keep each section short: what a designer or developer needs, nothing decorative. Never add a section, never rename one.', 'Job 3: writes the brief into the fixed section structure. Sections and their source fields come from onb_brief_sections.'),
  ('rewrite', 'Task: rewrite one section of the brief. The client read the section and told you what is wrong with it; their instruction is given below together with the whole current brief for context.

Rewrite ONLY the requested section. Apply the client''s instruction, keep everything they did not object to, and stay strictly within the client''s answers — do not add facts that are not in the answers, even if the instruction seems to ask for them; then add the missing item to still_needed instead. Same markdown subset and the same rules as for the brief. Answer in the client''s language.', 'Rewrite of ONE section after the client says what is wrong with it.'),
  ('assist', 'Task: rewrite one answer the client has just typed so it reads better, in the client''s language.

Rules, in order of importance:
- Use only what the client wrote. Never add a fact, a number, a date, a price, a duration, a place, a name or a claim that is not already in their answer.
- Keep their meaning and their voice. Plain words, short sentences, no marketing language, no superlatives.
- Keep it roughly the same length: tidy it up, make it concrete, do not pad it out.
- Return prose only. No markdown, no headings, no bullet points, no quotation marks around the whole answer.
- If their answer is already clear, return it with only small corrections.', 'Help me say this better: reshapes ONE answer into fuller prose. Suggestion only, the client accepts or rejects it.')
on conflict (id) do update set content = excluded.content, note = excluded.note;

insert into onb_examples (id, title, answers, brief, sort, active) values
  ('example_physio', 'Physiotherapiepraxis, 6 Seiten, Deutsch, Terminbuchung', '{"locale":"de","contact_company":"Physio Nordend","legal_name":"Physio Nordend Lena Hartmann e.K.","legal_form":"e.K.","address_city":"60318 Frankfurt am Main","service_scope":"one_region","regions_served":"Frankfurt Nordend, Bornheim, Westend","catalogue":"Krankengymnastik\nManuelle Therapie\nLymphdrainage\nHausbesuche","usps":"Termine innerhalb einer Woche, alle Kassen, barrierefreier Zugang","tagline":"__dont_know","booked_package":"gold","booked_page_band":"58","page_list":"Startseite\nLeistungen\n- Krankengymnastik\n- Manuelle Therapie\n- Lymphdrainage\nTeam\nKontakt & Anfahrt","visitor_action":"booking","tone_scale":3,"personality_scale":2,"references":[{"_id":"r1","url":"https://www.beispiel-physio.de","likes":"Ruhige Farben, große Fotos der Praxisräume, Termin-Button oben rechts","dislikes":"Zu viel Text auf der Startseite"}],"brand_colours":"#2A7F62, #F4F1EA","languages":"single","integrations":["booking","maps","reviews"],"booking_provider":"Doctolib","booking_account":"Lena Hartmann","gbp_link":"https://g.page/physio-nordend","legal_pages":"reuse","legal_reviewer":"Lena Hartmann","sells_to_consumers":"no","launch_date":"2026-11-02","launch_date_fixed":"no","content_ready_date":"2026-10-05","opening_hours":null}'::jsonb, '{"who":{"content_markdown":"Physio Nordend (Physio Nordend Lena Hartmann e.K.) ist eine Physiotherapiepraxis in 60318 Frankfurt am Main. Sie betreut Patientinnen und Patienten in Frankfurt Nordend, Bornheim und Westend.\n\nLeistungen, in der Schreibweise der Praxis:\n- Krankengymnastik\n- Manuelle Therapie\n- Lymphdrainage\n- Hausbesuche\n\nWarum Patienten sich für die Praxis entscheiden: Termine innerhalb einer Woche, alle Kassen, barrierefreier Zugang.","still_needed":["Slogan oder Claim (als „weiß ich nicht“ markiert)"],"sources":["contact_company","legal_name","address_city","regions_served","catalogue","usps"]},"goals":{"content_markdown":"Das Wichtigste, das ein Besucher tun soll: **einen Termin buchen**. Sehr wichtig ist außerdem der Anruf. Eher wichtig: der Besuch vor Ort und eine Anfrage. Kaufen und Anmelden spielen keine Rolle.","still_needed":[],"sources":["visitor_actions"]},"pages":{"content_markdown":"Gebucht: Paket Gold, 5–8 Seiten. Geplant sind 6 Seiten:\n- Startseite\n- Leistungen\n  - Krankengymnastik\n  - Manuelle Therapie\n  - Lymphdrainage\n- Team\n- Kontakt & Anfahrt","still_needed":[],"sources":["booked_package","booked_page_band","page_count","page_list"]},"look":{"content_markdown":"Tonalität: **Freundlich, aber professionell** (3 von 5). Persönlichkeit: **Dezent** (2 von 5).\n\nReferenz: https://www.beispiel-physio.de – gefällt: ruhige Farben, große Fotos der Praxisräume, Termin-Button oben rechts. Gefällt nicht: zu viel Text auf der Startseite.\n\nMarkenfarben: #2A7F62, #F4F1EA.","still_needed":["Fotos der Praxisräume","Angabe, ob ein Markenhandbuch existiert","Logo als Vektordatei – ja/nein"],"sources":["tone_scale","personality_scale","references","brand_colours"]},"dates":{"content_markdown":"Gewünschter Start: 2026-11-02 (nicht fest). Texte und Fotos liegen bis 2026-10-05 vor. Der Bau hängt an den Praxisfotos und dem Zugang zum Doctolib-Konto (Lena Hartmann).","still_needed":[],"sources":["launch_date","launch_date_fixed","content_ready_date","booking_account_holder"]}}'::jsonb, 10, true)
on conflict (id) do update set title = excluded.title, answers = excluded.answers, brief = excluded.brief, sort = excluded.sort, active = excluded.active;

-- Questions the new definition dropped: switched off, never deleted, so the answers
-- already given to them survive in the records that carry them.
update onb_fields set active = false where id in ('crm_name', 'payment_provider', 'booking_account_holder', 'payment_account_holder', 'newsletter_account_holder', 'crm_account_holder', 'publish_rights', 'public_pricing', 'pricing_detail', 'second_address', 'page_count', 'visitor_actions', 'premises_photos', 'maps_link', 'reviews_link', 'social_display', 'logo_vector', 'notice_logo_redraw', 'photo_source', 'accounts');

-- The timeline the 23 Sep 2026 terms describe: 10 days to the design, 3 weeks to build.
update app_settings set value = '3'::jsonb where key in ('onb_build_weeks_min', 'onb_build_weeks_max');
